package com.makefire.anonymous.aifactory.probes.factoryharness;

// Generated by the AI Factory (probe harness): the project's own test setup and authentication, proven on the unchanged
// application before the probe phase. Extend it in your probes and add only observations; do not edit it (the Factory
// checks it byte for byte) and do not declare profiles, mocks, configuration or authentication yourself.
@org.junit.jupiter.api.condition.EnabledIfSystemProperty(named = "factory.behavior.out", matches = ".+")
@org.springframework.boot.test.context.SpringBootTest(classes = com.makefire.anonymous.AnonymousApplication.class)
@org.springframework.test.context.ActiveProfiles("test")
@org.springframework.test.context.ContextConfiguration(initializers = FactoryProbeHarness.FactoryParityMocks.class)
public abstract class FactoryProbeHarness extends com.makefire.anonymous.support.SpringMockMvcTestSupport {

    // Built from the application's own web context (the same on Boot 2, 3 and 4; Java 8 source), through its own security
    // and filters: Spring Security's test support when the project's authentication needs it.
    @org.springframework.beans.factory.annotation.Autowired
    private org.springframework.web.context.WebApplicationContext factoryWebContext;
    private org.springframework.test.web.servlet.MockMvc factoryMvc;

    protected org.springframework.test.web.servlet.MockMvc factoryMvc() {
        if (factoryMvc == null) {
            org.springframework.test.web.servlet.setup.DefaultMockMvcBuilder builder =
                    org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup(factoryWebContext);
            java.util.List<Object> filters = new java.util.ArrayList<Object>();
            Class<?> filterType = factoryFilterType();
            java.util.Map<String, ?> filterBeans = factoryWebContext.getBeansOfType(filterType);
            for (java.util.Map.Entry<String, ?> entry : filterBeans.entrySet()) {
                if (false && "springSecurityFilterChain".equals(entry.getKey())) {
                    continue;
                }
                filters.add(entry.getValue());
            }
            for (Object bean : factoryWebContext.getBeansOfType(Object.class).values()) {
                String type = bean.getClass().getName();
                // Spring Security's chain is the springSecurityFilterChain bean (or the test configurer's), never twice
                if (type.endsWith("FilterRegistrationBean") && !type.contains("DelegatingFilterProxy")) {
                    try {
                        Object filter = bean.getClass().getMethod("getFilter").invoke(bean);
                        if (filterType.isInstance(filter) && !filters.contains(filter)) {
                            filters.add(filter);
                        }
                    } catch (ReflectiveOperationException e) {
                        // a registration bean without a filter: nothing to add
                    }
                }
            }
            org.springframework.core.annotation.AnnotationAwareOrderComparator.sort(filters);
            Object array = java.lang.reflect.Array.newInstance(filterType, filters.size());
            for (int i = 0; i < filters.size(); i++) {
                java.lang.reflect.Array.set(array, i, filters.get(i));
            }
            try {
                builder.getClass().getMethod("addFilters", array.getClass()).invoke(builder, array);
            } catch (ReflectiveOperationException e) {
                throw new IllegalStateException("the application's servlet filters could not be added", e);
            }

            factoryMvc = builder.build();
        }
        return factoryMvc;
    }

    // The servlet API the application runs on (javax on Boot 2, jakarta on Boot 3 and 4), from its own servlet context.
    private Class<?> factoryFilterType() {
        for (Class<?> type = factoryWebContext.getServletContext().getClass(); type != null; type = type.getSuperclass()) {
            for (Class<?> face : type.getInterfaces()) {
                if (face.getName().endsWith(".servlet.ServletContext")) {
                    try {
                        String api = face.getName().substring(0, face.getName().lastIndexOf('.'));
                        return Class.forName(api + ".Filter", false, face.getClassLoader());
                    } catch (ClassNotFoundException e) {
                        throw new IllegalStateException("no servlet Filter type beside " + face.getName(), e);
                    }
                }
            }
        }
        throw new IllegalStateException("the application's servlet context implements no servlet API");
    }

    /** The identity most of the project's own web tests sign in with (the default of signedIn and perform). */
    protected static final String DEFAULT_IDENTITY = "default";

    /** The request, signed in the way the project's own web tests sign in (DEFAULT_IDENTITY). */
    protected org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder signedIn(
            org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder request) {
        return signedInAs(request, DEFAULT_IDENTITY);
    }

    /**
     * The request, signed in exactly as the named project test signs in: a PREPARED_..._IDENTITY constant (the identity
     * the Factory proved that request with) or DEFAULT_IDENTITY. Every identity is copied from the project's own tests.
     */
    protected org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder signedInAs(
            org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder request, String identity) {
        if (DEFAULT_IDENTITY.equals(identity)) {
            return request;
        }
        throw new IllegalArgumentException("no identity of the project's tests is named " + identity);
    }

    /** Performs the request, signed in (DEFAULT_IDENTITY). */
    protected org.springframework.test.web.servlet.ResultActions perform(
            org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder request) throws Exception {
        return factoryMvc().perform(signedIn(request));
    }

    /** Performs the request signed in as the named identity (use a prepared request's own PREPARED_..._IDENTITY). */
    protected org.springframework.test.web.servlet.ResultActions performAs(
            org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder request, String identity)
            throws Exception {
        return factoryMvc().perform(signedInAs(request, identity));
    }

    // The identities to sign a request to the handler's controller and path with, in order (the smoke's): those of the
    // project tests of that controller or path first, then the others, most used first.
    static String[] factoryIdentities(String handlerType, String path) {
        String[] order = FactoryIdentityPlan.order(FACTORY_IDENTITIES, handlerType, path);
        return order.length == 0 ? new String[] {DEFAULT_IDENTITY} : order;
    }

    // How many of factoryIdentities(handlerType, path) are of the project tests of that controller or path.
    static int factoryOwnIdentities(String handlerType, String path) {
        return FactoryIdentityPlan.matched(FACTORY_IDENTITIES, handlerType, path);
    }

    // {id, tests, controllers, prefixes, named}: the identities copied from the project's tests (no values).
    private static final String[][] FACTORY_IDENTITIES = {
    };

    // Requests the Factory proved reach the application on the unchanged code ("METHOD /path"; observed status), each
    // with the identity it was proven with.
    /** Observed 200 on the unchanged application (http-json-converter). */
    protected static final String PREPARED_HTTP_JSON_CONVERTER_1 = "/board/lists";
    /** Observed 200 on the unchanged application (http-json-converter). */
    protected static final String PREPARED_HTTP_JSON_CONVERTER_2 = "/v1/healthCheck";
    /** Observed 200 on the unchanged application (http-json-media-type). */
    protected static final String PREPARED_HTTP_JSON_MEDIA_TYPE_1 = "/board/lists";
    /** Observed 200 on the unchanged application (http-json-media-type). */
    protected static final String PREPARED_HTTP_JSON_MEDIA_TYPE_2 = "/v1/healthCheck";
    /** Observed 200 on the unchanged application (http-json-config-response). */
    protected static final String PREPARED_HTTP_JSON_CONFIG_RESPONSE_1 = "/board/lists";
    /** Observed 200 on the unchanged application (http-json-config-response). */
    protected static final String PREPARED_HTTP_JSON_CONFIG_RESPONSE_2 = "/v1/healthCheck";
    /** Observed 200 on the unchanged application (http-json-config-request). */
    protected static final String PREPARED_HTTP_JSON_CONFIG_REQUEST_1 = "/board";
    /** The JSON body it was proven with (built from the handler's request type; placeholder values). */
    protected static final String PREPARED_HTTP_JSON_CONFIG_REQUEST_1_BODY = "{\"id\":1,\"title\":\"probe\",\"contents\":\"probe\",\"author\":\"probe\"}";
    /** Observed 200 on the unchanged application (http-json-config-request). */
    protected static final String PREPARED_HTTP_JSON_CONFIG_REQUEST_2 = "/board";
    /** The JSON body it was proven with (built from the handler's request type; placeholder values). */
    protected static final String PREPARED_HTTP_JSON_CONFIG_REQUEST_2_BODY = "{\"id\":1,\"title\":\"probe\",\"contents\":\"probe\",\"author\":\"probe\"}";

    // 2026-11-21 (run 816d289e) -- which of the project's own test identities signs a request of the probe harness, and in
    // which order the others are tried when it is forbidden. This source is COPIED into the generated FactoryProbeHarness
    // (ProbeHarness.harnessSource), which compiles in the customer's build at the base commit's level: fully qualified java.*
    // only (no imports) and Java 8 syntax (no records, var, List.of, switch expressions, text blocks or Stream.toList).
    // A row of the table: {id, tests, controllers, prefixes, named}: the identity's id (the project test it is copied from),
    // the number of tests using it, the controllers its tests name (@WebMvcTest), the path prefixes its tests send to, and the
    // controllers its tests are named after (FooControllerTest -> FooController), comma-separated. Rows are most-used first.
    // Order: the identities whose tests name the handler's controller; then those whose tests send to the request's path,
    // longest shared prefix first; then those whose tests are named after the controller; then every other identity, most
    // used first (the first row is the default when nothing matches).
    static final class FactoryIdentityPlan {

        private FactoryIdentityPlan() {
        }

        public static String[] order(String[][] table, String handlerType, String path) {
            java.util.List<String> out = new java.util.ArrayList<String>();
            if (table == null || table.length == 0) {
                return new String[0];
            }
            String controller = simpleName(handlerType);
            for (String[] row : table) {
                if (listed(row, 2, controller)) {
                    add(out, row[0]);
                }
            }
            String[] segments = segments(path);
            for (int score = segments.length; score >= 1; score--) {
                for (String[] row : table) {
                    if (prefixScore(row, segments) == score) {
                        add(out, row[0]);
                    }
                }
            }
            for (String[] row : table) {
                if (listed(row, 4, controller)) {
                    add(out, row[0]);
                }
            }
            for (String[] row : table) {
                add(out, row[0]);
            }
            return out.toArray(new String[0]);
        }

        // How many of order(table, handlerType, path) are identities of a test of that controller or path (the rest are
        // fallbacks: the most used first).
        public static int matched(String[][] table, String handlerType, String path) {
            int n = 0;
            if (table == null) {
                return 0;
            }
            String controller = simpleName(handlerType);
            String[] segments = segments(path);
            for (String[] row : table) {
                if (listed(row, 2, controller) || prefixScore(row, segments) > 0 || listed(row, 4, controller)) {
                    n++;
                }
            }
            return n;
        }

        // The best number of leading segments the request path shares with one of the row's prefixes: at least two, or the
        // whole prefix when it has one segment; 0 when none matches.
        static int prefixScore(String[] row, String[] segments) {
            if (row.length <= 3 || row[3] == null || row[3].isEmpty()) {
                return 0;
            }
            int best = 0;
            for (String prefix : row[3].split(",")) {
                String[] p = segments(prefix);
                int shared = 0;
                while (shared < p.length && shared < segments.length && p[shared].equals(segments[shared])) {
                    shared++;
                }
                if (p.length > 0 && shared >= Math.min(2, p.length) && shared > best) {
                    best = shared;
                }
            }
            return best;
        }

        static String[] segments(String path) {
            java.util.List<String> out = new java.util.ArrayList<String>();
            if (path != null) {
                String bare = path.indexOf('?') >= 0 ? path.substring(0, path.indexOf('?')) : path;
                for (String s : bare.split("/")) {
                    if (!s.isEmpty()) {
                        out.add(s);
                    }
                }
            }
            return out.toArray(new String[0]);
        }

        private static boolean listed(String[] row, int column, String name) {
            if (name == null || name.isEmpty() || row.length <= column || row[column] == null) {
                return false;
            }
            for (String listed : row[column].split(",")) {
                if (listed.equals(name)) {
                    return true;
                }
            }
            return false;
        }

        private static String simpleName(String type) {
            if (type == null) {
                return null;
            }
            String bare = type.indexOf('$') >= 0 ? type.substring(0, type.indexOf('$')) : type;
            return bare.substring(bare.lastIndexOf('.') + 1);
        }

        private static void add(java.util.List<String> out, String id) {
            if (id != null && !out.contains(id)) {
                out.add(id);
            }
        }
    }

    static class FactoryParityMocks implements org.springframework.context.ApplicationContextInitializer<
            org.springframework.context.ConfigurableApplicationContext> {
        private static final Class<?>[] MOCKED = {javax.cache.CacheManager.class};

        @Override
        @SuppressWarnings({"unchecked", "rawtypes"})
        public void initialize(org.springframework.context.ConfigurableApplicationContext context) {
            context.addBeanFactoryPostProcessor(factory -> {
                org.springframework.beans.factory.support.DefaultListableBeanFactory beans =
                        (org.springframework.beans.factory.support.DefaultListableBeanFactory) factory;
                for (Class<?> type : MOCKED) {
                    Object mock = org.mockito.Mockito.mock(type);
                    String[] names = beans.getBeanNamesForType(type, true, false);
                    boolean replaced = false;
                    for (String name : names) {
                        if (!beans.containsBeanDefinition(name)) {
                            System.out.println("factory-http-parity: " + name + " is a manually registered "
                                    + "singleton of " + type.getName() + "; left as it is");
                            continue;
                        }
                        org.springframework.beans.factory.config.BeanDefinition old = beans.getBeanDefinition(name);
                        org.springframework.beans.factory.support.RootBeanDefinition definition =
                                new org.springframework.beans.factory.support.RootBeanDefinition((Class) type,
                                        (java.util.function.Supplier) () -> mock);
                        if (old instanceof org.springframework.beans.factory.support.AbstractBeanDefinition) {
                            definition.copyQualifiersFrom(
                                    (org.springframework.beans.factory.support.AbstractBeanDefinition) old);
                        }
                        definition.setPrimary(old.isPrimary());
                        beans.removeBeanDefinition(name);
                        beans.registerBeanDefinition(name, definition);
                        replaced = true;
                    }
                    if (!replaced && names.length == 0) {
                        beans.registerSingleton("factoryParityMock_" + type.getName().replace('.', '_'), mock);
                    }
                }
            });
        }
    }
}
